(function(){'use strict';const G=Starfall,root=document.getElementById('app'),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let s=null,raw=null,storage=true,blocked=false,error='',tab='base',speed=5,crew=3,food=6,target='gather',short=false,priority='alloy',useTool=false,serial=0,signature='',held=false,pending=false,holdTimer=null,open=new Set(),lastWall=Date.now(),readReport=null,readRaid=null,selectedSite='wreck',legacyBackup=null,placeId='wall',placeX=2,placeY=7,placeRot=0,vehicle=false;const id=()=>Date.now().toString(36)+'-'+(++serial)+'-'+Math.random().toString(36).slice(2,7);const fmt=n=>{n=Math.max(0,Math.floor(Number(n)||0));return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;};const roleNames={standby:'待命／留守',recycle:'回收',supply:'補給',duty:'值守',patrol:'巡衛',ward:'守陣',away:'外拓',job:'施工／訓練',dead:'永久陣亡',garrison:'據點留守'};
// Alpha 10.1: presentation-only state. No changes to the core or save schema.
let screen='title',prologue=0,settingsOpen=false,audioEnabled=false,motionEnabled=true,radioFilter='all',restartPending=false,audioCtx=null;
// Independent UI preferences; never change the game save schema.
const PREF_KEY='starfall.colony.preferences.v1',FEEDBACK_TO='wongmk@gmail.com',FEEDBACK_VERSION='Alpha 10.1D QA-R2';
let volume=60,textSize=100,radioSound=true,alarmSound=true,clickSound=true,prefNotice='';
function loadPrefs(){try{const p=JSON.parse(localStorage.getItem(PREF_KEY)||'null');if(!p||typeof p!=='object')return;if(typeof p.audio==='boolean')audioEnabled=p.audio;if(typeof p.motion==='boolean')motionEnabled=p.motion;if([0,25,50,60,75,100].includes(p.volume))volume=p.volume;if([100,115,130].includes(p.textSize))textSize=p.textSize;if([1,5,15].includes(p.speed))speed=p.speed;if(typeof p.radio==='boolean')radioSound=p.radio;if(typeof p.alarm==='boolean')alarmSound=p.alarm;if(typeof p.click==='boolean')clickSound=p.click;}catch(_){prefNotice='無法讀取偏好設定；使用預設或本次設定。';}}
function savePrefs(){try{localStorage.setItem(PREF_KEY,JSON.stringify({audio:audioEnabled,motion:motionEnabled,volume,textSize,speed,radio:radioSound,alarm:alarmSound,click:clickSound}));prefNotice='';}catch(_){prefNotice='無法保存偏好設定；本次頁面仍然有效。';}}
function applyPrefs(){document.documentElement.style.fontSize=textSize===100?'':textSize+'%';}
function prefOptions(values,current,suffix){return values.map(v=>`<option value="${v}" ${v===current?'selected':''}>${v}${suffix}</option>`).join('');}
function feedbackDialog(){let d=document.getElementById('feedback-dialog');if(!d){d=document.createElement('dialog');d.id='feedback-dialog';d.className='feedback-dialog';d.setAttribute('aria-labelledby','feedback-title');d.innerHTML=`<form><div class="feedback-head"><div><div class="eyebrow">STARFALL / FIELD REPORT</div><h2 id="feedback-title">意見回饋</h2></div><button type="button" id="feedback-close" aria-label="關閉意見回饋">✕</button></div><p>多謝你協助改善前哨。</p><p class="muted">收件人：${FEEDBACK_TO}<br>版本：${FEEDBACK_VERSION}</p><label class="field">意見類別<select id="feedback-type"><option>功能建議</option><option>錯誤回報</option><option>遊玩體驗</option><option>其他</option></select></label><label class="field">意見內容（必填）<textarea id="feedback-text" rows="5" maxlength="1200" required placeholder="例如：發生了甚麼？怎樣重現？希望如何改善？"></textarea></label><p class="muted">只包含你輸入的內容、類別及版本，不附上存檔、帳號或裝置資料。請勿填寫密碼等私人資料。遊戲仍按原時間規則運作，可先暫停。</p><button class="primary full" type="submit">開啟電郵草稿</button><button class="full" type="button" id="feedback-copy">複製意見內容</button><p id="feedback-status" role="status" class="muted">草稿需要你在郵件程式按下寄出；本遊戲不會自動寄信。</p><label class="field" id="feedback-fallback" hidden>手動複製以下內容<textarea id="feedback-copy-text" rows="4" readonly></textarea></label></form>`;document.body.appendChild(d);
const form=d.querySelector('form'),input=d.querySelector('#feedback-text'),status=d.querySelector('#feedback-status');
const content=()=>{const msg=input.value.trim();if(!msg){input.setCustomValidity('請先填寫意見內容。');input.reportValidity();return null;}const type=d.querySelector('#feedback-type').value;return {subject:`【墜星前哨】${type} · ${FEEDBACK_VERSION}`,body:`類別：${type}\r\n版本：${FEEDBACK_VERSION}\r\n\r\n${msg.replace(/\r?\n/g,'\r\n')}`};};
const fallback=c=>{const t=d.querySelector('#feedback-copy-text');t.value=`收件人：${FEEDBACK_TO}\n主旨：${c.subject}\n\n${c.body}`;d.querySelector('#feedback-fallback').hidden=false;t.focus();t.select();};
input.addEventListener('input',()=>{input.setCustomValidity('');d.querySelector('#feedback-fallback').hidden=true;});
form.addEventListener('submit',e=>{e.preventDefault();const c=content();if(!c)return;const url='mailto:'+FEEDBACK_TO+'?subject='+encodeURIComponent(c.subject)+'&body='+encodeURIComponent(c.body);if(url.length>7500){fallback(c);status.textContent='內容較長，請複製後貼到 Gmail 或其他郵件程式寄出。';return;}status.textContent='已要求開啟郵件草稿，尚未寄出。如果沒有開啟，請複製內容並手動寄送。';const a=document.createElement('a');a.href=url;a.click();});
d.querySelector('#feedback-copy').addEventListener('click',async()=>{const c=content();if(!c)return;fallback(c);try{await navigator.clipboard.writeText(d.querySelector('#feedback-copy-text').value);status.textContent='已複製，請貼到 Gmail 或其他郵件程式寄出。';}catch(_){status.textContent='已選取內容，請長按或使用系統複製，再貼到 Gmail 寄出。';}});
d.querySelector('#feedback-close').addEventListener('click',()=>d.close());d.addEventListener('close',()=>root.querySelector('[data-action="feedback"]')?.focus({preventScroll:true}));}if(!d.open)d.showModal();}
const seenRX=new Set();let knownRX=new Set(),lastWarning=null;let readOnlyReplay=false,loadedWall=null,loadedAt=null,needsMigration=false,storageConflict=false,archivedLegacy=null;
const introScenes=[['航道失效','遠燈號 · 航行紀錄','導航失去回應。船身正在偏離預定航道。','「所有人員，立即進入緊急避難位置！」'],['墜落','緊急紀錄 · 通訊中斷','船體在陌生星球的岩谷中解體。岑曜從殘骸旁醒來。','「這裡不是我們預定降落的地方。」'],['六名生還者','名冊 · 臨時集合','六名可派遣人員已集合。其餘同伴仍然下落不明，物資只夠支撐最初的行動。','「長官，我們要先把物資帶回來。」'],['微弱的希望','備用電台 · 開機紀錄','手持電台仍可運作，現在只有雜訊。先採集、返營，再逐步建立基地與對外聯絡。','「只要還有人活著，就有重建的可能。」']];
function radioRX(){return s?Object.values(s.radio.threads).flatMap(t=>t.messages.filter(m=>m.side==='remote')):[];}
function unreadRX(k){return (s?.radio.threads[k]?.messages||[]).filter(m=>m.side==='remote'&&!seenRX.has(m.id)).length;}
function sound(kind){if(!audioEnabled||volume===0||(kind==='rx'&&!radioSound)||(kind==='alarm'&&!alarmSound)||(kind==='click'&&!clickSound))return;try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;if(!audioCtx)audioCtx=new A();if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});if(audioCtx.state!=='running')return;const t=audioCtx.currentTime;for(const [i,f] of (kind==='alarm'?[330,240,330]:kind==='rx'?[620,840]:[440]).entries()){const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=kind==='alarm'?'triangle':'sine';o.frequency.value=f;g.gain.setValueAtTime(0,t+i*.11);g.gain.linearRampToValueAtTime(.055*volume/100,t+i*.11+.012);g.gain.exponentialRampToValueAtTime(.001*volume/100,t+i*.11+.09);o.connect(g);g.connect(audioCtx.destination);o.start(t+i*.11);o.stop(t+i*.11+.10);}}catch(_){/* audio is optional */}}
function notifications(){const now=new Set(radioRX().map(m=>m.id)),warning=s?.baseRaid?.id||null;if(screen==='game'){if([...now].some(id=>!knownRX.has(id)))sound('rx');if(warning&&warning!==lastWarning)sound('alarm');}knownRX=now;lastWarning=warning;}
function settings(){return `<section class="panel settings-panel" aria-label="顯示與音效設定"><h2>終端設定</h2><h3>音效與顯示</h3>${action('音效：'+(audioEnabled?'開啟':'關閉'),'audio-toggle','full')}<label class="field">音量<select id="pref-volume">${prefOptions([0,25,50,60,75,100],volume,'%')}</select></label>${action('收訊提示：'+(radioSound?'開啟':'關閉'),'pref-radio','full')}${action('警報提示：'+(alarmSound?'開啟':'關閉'),'pref-alarm','full')}${action('按鍵提示：'+(clickSound?'開啟':'關閉'),'pref-click','full')}${action('動畫：'+(motionEnabled?'開啟':'減少'),'motion-toggle','full')}<label class="field">文字大小<select id="pref-text">${prefOptions([100,115,130],textSize,'%')}</select></label><p class="muted">系統減少動畫偏好永遠優先。${prefNotice?esc(prefNotice):'偏好設定獨立保存，不會修改遊戲存檔。'}</p><h3>遊戲與存檔</h3><label class="field">模擬速度<select id="pref-speed">${prefOptions([1,5,15],speed,'×')}</select></label>${raw!==null?action('匯出目前存檔','backup-save','full'):''}${archivedLegacy?action('匯出升級前備份','backup-legacy','full'):''}${screen==='game'?action('返回主畫面','settings-title','full'):''}<h3>支援與回饋</h3>${action('意見回饋／回報問題','feedback','primary full')}<p class="muted">由玩家自行確認寄出電郵，遊戲不會自動傳送資料。</p>${action('關閉設定','settings','full')}</section>`;}
function landscape(){return `<svg class="crash-landscape" viewBox="0 0 600 420" aria-hidden="true"><defs><linearGradient id="crashsky" x2="0" y2="1"><stop stop-color="#081420"/><stop offset=".7" stop-color="#2f4a58"/><stop offset="1" stop-color="#9b7c63"/></linearGradient><linearGradient id="hull" x2="0" y2="1"><stop stop-color="#9ba8a7"/><stop offset=".35" stop-color="#5b6c75"/><stop offset="1" stop-color="#1c303c"/></linearGradient><radialGradient id="glow"><stop stop-color="#edac65" stop-opacity=".85"/><stop offset="1" stop-color="#edac65" stop-opacity="0"/></radialGradient></defs><rect width="600" height="420" fill="url(#crashsky)"/><g fill="#b9d6dc" opacity=".75">${Array.from({length:45},(_,i)=>`<circle cx="${(i*137+23)%600}" cy="${(i*53+11)%157}" r="${i%7===0?1.5:.7}"/>`).join('')}</g><circle cx="476" cy="91" r="57" fill="#b5d2d2" opacity=".72"/><path d="M423 91q52 12 106-16M431 111q42 9 89-13" stroke="#718f9d" fill="none" opacity=".55"/><path d="M0 252L68 126 113 202 172 148 245 257 324 183 370 229 451 141 509 221 600 162V420H0Z" fill="#263b46"/><path d="M0 297L88 216 165 280 230 229 340 288 428 231 511 286 600 231V420H0Z" fill="#33454b"/><path d="M0 318L118 290 242 330 382 294 600 322V420H0Z" fill="#333b3e"/><path d="M0 376L162 340 331 370 600 336V420H0Z" fill="#17262e"/><ellipse cx="408" cy="315" rx="118" ry="58" fill="url(#glow)" opacity=".28"/><g transform="translate(235 241) rotate(-13)"><path d="M0 55L32 16 204 3 250 37 214 74 50 82Z" fill="url(#hull)" stroke="#a4b4b5" stroke-width="1.5"/><path d="M38 21L195 9 219 29 43 42Z" fill="#1d3b48"/><path d="M44 26L177 16M59 44l130-10M51 68l147-8" stroke="#a4b4b5" opacity=".55"/><path d="M121 11l-15 33 16 19-12 15M183 9l-10 25 13 11-8 25" stroke="#101d27" stroke-width="3" fill="none"/><path d="M21 56l-38 10-11 14 54-7M222 62l25 25 28 1-29-36" fill="#445963"/><rect x="50" y="49" width="11" height="4" fill="#d78c55"/><rect x="187" y="43" width="13" height="4" fill="#ffad67" class="beacon"/></g><g transform="translate(70 306)"><path d="M0 50L33 0 67 50Z" fill="#9c9780"/><path d="M33 0v50l20-3Z" fill="#485e60"/><path d="M14 49L33 20 47 49Z" fill="#263a43"/><rect x="74" y="33" width="26" height="18" rx="2" fill="#778487"/><path d="M76 38h22m-11-5v18" stroke="#323f43"/><path d="M115 50V7m-11 12l11-12 11 12" stroke="#8eb6bb" stroke-width="2" fill="none"/><circle cx="115" cy="7" r="3" fill="#e7ae65" class="beacon"/></g><ellipse cx="157" cy="365" rx="43" ry="21" fill="url(#glow)" opacity=".5"/><path d="M152 367l6-12 5 12Z" fill="#ffc176"/><path d="M0 395L600 380V420H0Z" fill="#0d1b24"/><g fill="#4e6167" opacity=".65"><path d="M20 384l19-12 12 10Z M217 374l22-13 14 13Z M510 370l20-18 20 16Z"/></g></svg>`;}
function titlePage(){const has=!!s;return `<div class="wrap launch-wrap"><section class="launch-card">${landscape()}<div class="launch-content"><div class="eyebrow"><span class="led amber"></span> 遠燈號 / 緊急紀錄 / ALPHA 10.1D</div><h1>墜星前哨</h1><div class="launch-en">S T A R F A L L</div><p class="launch-sub">失落的訊號 · THE LOST SIGNAL</p><p>我們失去了航道，卻還沒有失去未來。</p>${error?`<p class="notice" role="alert">${esc(error)}</p>`:''}${has?`<p class="save-note">已找到前哨 · 模擬時間 ${fmt(s.time)} · ${G.B(s)}名兵員</p>${action('繼續前哨','continue','primary full')}${action('重新開局','new-journey','full')}`:`<button class="primary full" data-action="new-journey" ${blocked?'disabled':''}>開始新旅程</button>`}${raw!==null?action('匯出原始存檔','backup-save','full'):''}<div class="launch-links">${action('世界檔案','archive')}${action('遊戲設定','settings')}</div>${settingsOpen?settings():''}<p class="muted">離線試玩 · 未部署網站 · 目前 ${speed}倍模擬速度，可隨時切換。</p></div></section></div>`;}
function introPage(){const d=introScenes[prologue];return `<div class="wrap launch-wrap"><section class="launch-card intro-scene">${landscape()}<div class="launch-content"><div class="eyebrow">事故紀錄 0${prologue+1} / 04 · ${d[1]}</div><div class="chapter-track">${introScenes.map((_,i)=>`<i class="${i<=prologue?'active':''}"></i>`).join('')}</div><h1>${d[0]}</h1><p class="story-text">${d[2]}</p><blockquote>${d[3]}</blockquote><p class="muted">序章閱讀不消耗遊戲時間。</p>${prologue===3?action(readOnlyReplay?'返回世界檔案':'開始重建',readOnlyReplay?'archive':'start','primary full'):action('繼續紀錄','intro-next','primary full')}${prologue<3?action('略過其餘紀錄','intro-skip','full'):''}<div class="launch-links">${action('上一幕','intro-prev')}${action('返回標題','title')}</div></div></section></div>`;}
function archivePage(){return `<div class="wrap launch-wrap"><section class="panel"><div class="eyebrow">遠燈號 / 公開事故檔案</div><h1>世界檔案</h1><p>事故：航道失效、墜落岩谷、通訊中斷。指揮官岑曜及六名兵員建立臨時營地。五位失散同伴須經真實核實與接應才能歸隊。</p><p>先外拓採集，再建造、製造、聯絡其他勢力。永久陣亡的兵員不會復活；基地可透過接納及訓練新人擴張。</p><p class="muted">此檔案不揭露未核實人物姓名及後續劇情。</p>${action('回看序章','replay-intro','full')}${action('返回標題','title','primary full')}</section></div>`;}
function markRadio(k){for(const m of s.radio.threads[k]?.messages||[])if(m.side==='remote')seenRX.add(m.id);}
function load(){try{raw=localStorage.getItem(G.KEY);if(raw!==null){const w=JSON.parse(raw);const migrated=G.migrate(w.state);if(!migrated||!Number.isFinite(w.wall)||w.wall<0)throw Error('存檔不相容或損壞，已保留原資料');needsMigration=w.state.schema!==migrated.schema;legacyBackup=needsMigration?raw:null;archivedLegacy=legacyBackup;if(!archivedLegacy){for(const v of [6,5,4,3,2]){const b=localStorage.getItem(G.KEY+'.backup.schema'+v);if(b){archivedLegacy=b;break;}}}s=migrated;loadedWall=w.wall;loadedAt=Date.now();lastWall=w.wall;}}catch(e){if(raw!==null){blocked=true;error=e.message;s=null;}else{storage=false;error='瀏覽器不允許本機儲存；本次只可在目前頁面遊玩。';}}}
function commit(next){if(!G.validate(next))throw Error('狀態驗證失敗');const n=G.clone(next);n.revision=(s?.revision||0)+1;const wall=Date.now(),v=JSON.stringify({state:n,wall});if(storage){try{if(localStorage.getItem(G.KEY)!==raw){storageConflict=true;blocked=true;throw Error('另一分頁已修改存檔，請重新載入。');}if(legacyBackup){const schema=JSON.parse(legacyBackup).state.schema,key=G.KEY+'.backup.schema'+schema,prior=localStorage.getItem(key);if(prior===null)localStorage.setItem(key,legacyBackup);else if(prior!==legacyBackup)throw Error('舊版備份已存在且內容不同；未覆寫，請先匯出存檔。');}localStorage.setItem(G.KEY,v);raw=v;}catch(e){error='未能儲存：'+e.message;return false;}}s=n;lastWall=wall;legacyBackup=null;needsMigration=false;notifications();return true;}
function continueGame(){if(blocked||!s)return false;try{if(storage&&localStorage.getItem(G.KEY)!==raw){storageConflict=true;blocked=true;error='另一分頁已修改存檔，請重新載入。';return false;}const d=s.paused?0:Math.min(900,Math.max(0,Math.floor(((loadedAt??Date.now())-(loadedWall??lastWall))/1000)));if((d||needsMigration)&&!commit(G.advance(s,d,{offline:true})))return false;loadedWall=null;screen='game';lastWall=Date.now();knownRX=new Set(radioRX().map(m=>m.id));lastWarning=s.baseRaid?.id||null;return true;}catch(e){error='無法繼續：'+e.message;return false;}}
function command(c){if(!s||blocked)return;const r=G.act(s,{...c,idempotency:id()});if(!r.ok){error=r.error;render(true);return;}if(commit(r.state)){error='';render(true);}else render(true);}
const cmd=(label,c,cls='')=>{const why=blocked?'存檔已停止；請匯出備份並重新載入。':G.reason(s,c);return `<button class="${cls}" data-cmd="${esc(JSON.stringify(c))}" ${why?'disabled':''} title="${esc(why)}">${esc(label)}</button><span class="reason" data-reason>${esc(why)}</span>`};const action=(label,a,cls='')=>`<button class="${cls}" data-action="${a}" ${blocked&&['continue','new-journey','start'].includes(a)?'disabled':''}>${esc(label)}</button>`;const stat=(key,label,v)=>`<div class="stat"><strong data-stat="${key}">${v}</strong><span>${label}</span></div>`;const count=r=>G.role(s,r).length;
function art(k,built=true){const level=k==='command'?s.build.command:k==='wall'?s.build.wall:k==='recycle'&&s.build.deep||k==='supply'&&s.build.dense?2:built?1:0;let path={recycle:'<path d="M20 62V35L45 20 72 35V62Z" fill="#5e8490"/><path d="M72 62V40L99 25 128 40V62Z" fill="#7c9aa0"/><path d="M28 42h34M80 47h37" stroke="#d5b482" stroke-width="4"/>',supply:'<path d="M16 62V38Q80 -8 144 38V62Z" fill="#426c65" stroke="#9fc9a6" stroke-width="2"/><path d="M42 62V28M80 62V16M118 62V28" stroke="#9fc9a6"/><path d="M33 54l8-9 8 9m20 0 8-9 8 9m20 0 8-9 8 9" stroke="#9de0a6" fill="none"/>',armory:'<path d="M25 62V28L80 13 135 28V62Z" fill="#5d747e"/><path d="M60 62V35h40v27" fill="#243b46"/><path d="M30 31h100" stroke="#e5b87c" stroke-width="3"/>',command:'<path d="M22 62V31L80 17 138 31V62Z" fill="#537b89"/><path d="M80 17V4m-18 6 18 7 18-7" stroke="#9cdbc8" stroke-width="2" fill="none"/><rect x="43" y="35" width="74" height="16" rx="3" fill="#183a45"/><path d="M52 43h13m10 0h13m10 0h10" stroke="#8ed6bf" stroke-width="3"/>',housing:'<path d="M15 62V42L47 16 79 42V62Z M82 62V42l32-26 32 26v20Z" fill="#8c9c91"/><path d="M40 62V44h14v18m53 0V44h14v18" fill="#31434a"/>',wall:'<path d="M10 62V28h24v12h24V28h24v12h24V28h24v12h20v22Z" fill="#77868b"/><path d="M10 51h140" stroke="#e3bc80" stroke-width="3"/>',tower:'<path d="M60 62l8-35h24l8 35M54 28V12h52v16Z" fill="#7b9ba3" stroke="#a9c8cc"/><path d="M80 12V2" stroke="#a8e6c9" stroke-width="3"/>'}[k]||'';return `<div class="art ${built?'':'unbuilt'}"><svg viewBox="0 0 160 72" role="img" aria-label="${built?'已啟用':'未建'}設施"><path d="M0 63L160 63" stroke="#7e8e86"/>${path}${level>=2?'<path d="M19 64h122M28 56h104" stroke="#9ce0c9" stroke-width="2"/><rect x="130" y="7" width="18" height="10" rx="2" fill="#d6ab67"/>':''}</svg><span class="art-level">${built?'L'+level:'未建'}</span></div>`;}
function scene(){return `<div class="scene camp-scene"><svg viewBox="0 0 360 126" role="img" aria-label="岩谷營地，遠方失事船體"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#132c40"/><stop offset="1" stop-color="#45606a"/></linearGradient></defs><rect width="360" height="126" fill="url(#sky)"/><circle cx="285" cy="25" r="15" fill="#b2c9c8" opacity=".75"/><g fill="#d3e7dc" opacity=".8"><circle cx="25" cy="15" r="1"/><circle cx="85" cy="25" r="1"/><circle cx="164" cy="10" r="1"/><circle cx="230" cy="22" r="1"/></g><path d="M0 74L35 35 80 62 112 41 155 79 205 52 260 76 308 42 360 63V126H0Z" fill="#3c4a4c"/><path d="M0 93L60 76 130 95 210 79 280 91 360 74V126H0Z" fill="#615d55"/><path d="M0 112L360 105V126H0Z" fill="#373c3c"/><g transform="translate(232 68) rotate(-12)"><path d="M0 12L72 0 95 16 64 26 0 23Z" fill="#74868b"/><path d="M20 10h38l12 8H20Z" fill="#294854"/><path d="M64 26l12 9" stroke="#d2a574" stroke-width="3"/></g><path d="M34 110L64 78 94 110Z" fill="#9c9d83"/><path d="M64 78v32" stroke="#3d4b48" stroke-width="2"/><rect x="106" y="101" width="20" height="10" fill="#ad9a71"/>${s.first?'<rect x="142" y="88" width="34" height="22" fill="#719098"/><path d="M138 88h42l-9-7h-24Z" fill="#b7c3b8"/>':''}${s.build.housing?'<path d="M183 110V91l16-12 16 12v19Z" fill="#9caa98"/>':''}${s.build.wall?'<path d="M7 113v-13h12v7h12v-7h12v13" fill="#87979b"/>':''}${s.build.supply?'<path d="M105 94v-14q14-20 28 0v14Z" fill="#6f9e82"/>':''}${s.build.tower?'<path d="M25 100l5-35h10l5 35M25 65h20V52H25Z" stroke="#bdc3b5" fill="#627c83"/><circle cx="35" cy="50" r="2" fill="#f1b567"/>':''}${s.build.armory?'<rect x="220" y="95" width="28" height="16" fill="#788d94"/><path d="M217 95h34l-6-5h-22Z" fill="#b7c7c8"/>':''}${s.frontier.energy?'<path d="M154 81v-20h12v20M150 62h20" stroke="#87e6cf" fill="#477a7a"/>':''}<circle cx="102" cy="110" r="2" fill="#f6ce89"/></svg><div class="caption"><span class="eyebrow">FIELD CAMERA / 岩谷</span><strong>${s.first?(s.frontier.level?'殖民前哨':'重建營地'):'事故後・臨時營地'}</strong><span> ${s.baseRaid?'外圍警戒':'現地狀態紀錄'}</span></div></div>`;}
function assign(k){return `<div class="assign">${cmd('−',{type:'assign',role:k,delta:-1}).replace(/<span class="reason" data-reason>.*?<\/span>/,'')}<b data-count="${k}">${count(k)}</b>${cmd('＋',{type:'assign',role:k,delta:1}).replace(/<span class="reason" data-reason>.*?<\/span>/,'')}</div><div class="reason" data-assign-reason="${k}">${esc(G.reason(s,{type:'assign',role:k,delta:1}))}</div>`;}
function buildBtn(k){const d=G.BUILD[k];return cmd(`${d.name} · ${d.cost}合金 · ${d.secs}秒`,{type:'build',target:k},'full');}
function card(k,title,built,content,detail){const map={MED:'command',SCR:'recycle',WAT:'supply',RAD:'command',GATE:'armory'};const marks=Object.keys(map).filter(id=>map[id]===k&&s.companions[id].project).map(id=>`<div class="accent muted">✓ ${esc(G.COMP[id].project)}</div>`).join('');return `<article class="card">${art(k,built)}<h3>${title}</h3>${content}${marks}<details data-detail="${k}" ${open.has(k)?'open':''}><summary>操作／成本</summary><div>${detail}</div></details></article>`;}
function base(){const b=s.build;let h=scene()+`<section class="panel"><h2>${s.first?'重建指令':'先把物資帶回來'}</h2><p>${s.first?'安排回收與補給，留出守備人員。住棚、整備艙及指揮艙可逐步擴充編制。':'第一趟物資仍未帶回營地。安排可用兵員前往近側殘骸，保留足夠守備；首趟真返營後才能開始建設。'}</p>${action(s.mission?'查看外拓隊':'前往外拓','tab-explore','primary')}</section>`;if(!s.first)return h;h+=`<section class="panel logistics-shortcut"><div class="row"><div><h3>物流與製造</h3><p>倉庫 <b data-stock-used>${G.used(s)}</b>／${G.capacity(s)} 重量</p></div>${action('開啟倉庫與工作台','tab-storage','primary')}</div></section>`;h+=`<div class="grid">${card('recycle','回收工具台',true,`<div class="status">每30秒／人 +1合金${b.deep?' · 深拆✓':''}</div>${assign('recycle')}`,b.deep?'深拆已完成；有工人及值守才額外+1合金。':buildBtn('deep'))}${card('supply','補給棚',!!b.supply,`<div class="status">${b.supply?'每30秒／人 +2口糧':'未建造'}${b.dense?' · 密植✓':''}</div>${assign('supply')}`,!b.supply?buildBtn('supply'):b.dense?'密植已完成；有工人及值守才額外+1口糧。':buildBtn('dense'))}${card('armory','整備艙',!!b.armory,`<div class="status">巡衛 <b data-count="patrol">${count('patrol')}</b> · 守陣 <b data-count="ward">${count('ward')}</b></div>`,!b.armory?buildBtn('armory'):cmd('巡衛訓練 · 3糧2金／30秒',{type:'train',target:'patrol'},'full')+cmd('守陣訓練 · 4糧1金／30秒',{type:'train',target:'ward'},'full')+cmd('遣返巡衛 · 30秒',{type:'recall',target:'patrol'},'full')+cmd('遣返守陣 · 30秒',{type:'recall',target:'ward'},'full'))}${card('command',b.command===2?'指揮艙 L2':'指揮記錄桌',true,`<div class="status">兵員容量 ${G.cap(s)} · 值守 <b data-count="duty">${count('duty')}</b>/1</div>${assign('duty')}`,b.command===1?buildBtn('command'):'容量由殖民指揮研究逐步提升；新人仍須真接納及訓練。')}</div><h2 style="margin-top:16px">營地擴建</h2><div class="grid">${card('housing','住棚',!!b.housing,`<div class="status">床位 ${G.beds(s)} · 已建 ${b.housing}座</div>`,buildBtn('housing'))}${card('wall','防禦路障',!!b.wall,`<div class="status">耐久 ${s.wallHp}/3 · ${G.wallPower(s)?'實際防禦+'+G.wallPower(s):'目前無防護貢獻'}</div>`,!b.wall?buildBtn('wall'):(b.wall===1?cmd('合金圍牆 · 8合金／30秒',{type:'build',target:'wall'},'full'):'合金圍牆已建。')+cmd('修理 +1耐久 · 2合金／60秒',{type:'repair'},'full'))}${card('tower','瞭望塔',!!b.tower,`<div class="status">${b.tower?'有值守時預警60秒':'未建；基礎預警30秒'}</div>`,b.tower?'須有真實指揮值守兵員。':buildBtn('tower'))}</div>`;if(s.residents.length){h+=`<section class="panel"><h2>居民入伍</h2><p class="muted">自願訓練：3糧、2合金、120秒，佔用一名待命教官。完成才增加兵員，總人口不變。</p>${s.residents.map(p=>`<div class="event">${esc(p.name)} ${cmd('訓練為T1兵員',{type:'recruit',target:p.id})}</div>`).join('')}</section>`;}h+=`<section class="panel"><h2>星域擴展 / 07–10</h2>${action('基地空間佈局','tab-layout','full primary')}${action('殖民發展與勢力','tab-frontier','full primary')}</section>`;h+=military();return h;}
function military(){const o=s.ops||{};return `<section class="panel" id="military"><h2>軍備與部隊升級</h2><p>指揮艙L2開放2支隊伍；T2需整備艙、2座住棚、工坊與研究。升階不增加人口。</p><p>工坊 ${o.workshop?'L2 ✓':'未建'} · 整備 ${o.academy?'L2 ✓':'L1'} · 研究 ${o.research?'完成':'未完成'} · 庫存 ${o.kits||0}套</p>${cmd('工坊L2 · 10合金／120秒',{type:'workshop'},'full')}${cmd('整備L2 · 12合金／120秒',{type:'academy'},'full')}${cmd('基礎研究 · 8合金／120秒',{type:'research'},'full')}${cmd('製造T2標準裝備 · 3合金／120秒',{type:'fabricate'},'full')}<p class="muted">每套脈衝器／護具給一名兵，T2裝備耐久大於0時，該兵參戰+1；每場參戰耗10耐久。0耐久僅保留T1基礎戰力。</p>${s.crew.filter(p=>p.alive).map(p=>`<div class="event">${esc(p.name)} · T${p.tier} · ${roleNames[p.role]} ${p.tier===1?cmd('升T2 · 4糧3金＋1套／180秒',{type:'promote',target:p.id},'full'):cmd('修復裝備至100% · 2金／60秒',{type:'kitrepair',target:p.id},'full')}${p.tier===2?'裝備 '+p.kit+'%':''}</div>`).join('')}</section>`;}
function itemList(items){return Object.entries(items).filter(([,n])=>n).map(([k,n])=>`${esc(G.ITEMS[k].name)} × ${n}`).join('、')||'無';}
function storagePage(){const l=s.logistics;const u=G.used(s),cap=G.capacity(s);return `<section class="panel inventory"><div class="tag">LOGISTICS / 06</div><h2>倉庫與工作台</h2><p>共享容量 <strong data-stock-used>${u}</strong> / ${cap} 重量 · 貨架 ${l.racks}座</p><div class="meter" role="presentation"><i data-stock-bar style="width:${Math.min(100,u/cap*100)}%"></i></div><p data-stock-note class="gold">${u>cap?'超額存放：保留既有物資，先消耗或擴倉。':u===cap?'倉庫已滿：生產及入庫暫停。':'尚有 '+(cap-u)+' 重量空間。'}</p><div class="inventory-grid">${Object.entries(G.ITEMS).map(([k,d])=>`<div class="item-card"><small>${esc(d.name)} · 重${d.weight}</small><strong data-item="${k}">${G.stock(s,k)}</strong></div>`).join('')}</div><p class="muted">配裝武器屬士兵，不計倉庫。合金與口糧仍是原有建造及訓練資源。</p></section><section class="panel"><h2>返營卸貨區</h2>${Object.entries(l.unload).length?Object.entries(l.unload).map(([slot,v])=>`<div class="event"><h3>背包 ${slot} · ${esc(v.id)}</h3><p>${itemList(v.items)}</p>${cmd('將可容納物資入庫',{type:'unload',slot:Number(slot),trip:v.id},'full')}${cmd('放棄剩餘物資（不可復原）',{type:'discard_unload',slot:Number(slot),trip:v.id,confirm:true},'full warn')}</div>`).join(''):'<p>全部背包已清空，沒有待卸貨物。</p>'}<p class="muted">卸貨未清空的背包不能再次派遣；士兵已返營，可正常守備。</p></section><section class="panel"><h2>加工與製造</h2><p>單一工位；每項需要1名待命兵。開始才扣費，完成才發貨。</p>${Object.keys(l.output).length?`<p class="gold">待入庫成品：${itemList(l.output)}</p>${cmd('領取成品',{type:'output'},'full primary')}`:'<p class="muted">工單輸出格：空</p>'}${s.job?.type==='process'?cmd('取消目前工單（材料不退）',{type:'cancel_process',confirm:true},'full warn'):''}${Object.entries(G.RECIPES).map(([k,d])=>`<article class="recipe"><h3>${esc(d.name)}</h3><p>${itemList(d.cost)} → ${k==='rack'?'容量 +100':itemList(d.out)} · ${d.secs}秒</p><small>${k==='tool'?'需工坊L2；設備箱額外拆取1零件（單次）':k==='rack'?'需指揮艙L2；回收台施工':'回收工具台；1名操作員'}</small>${cmd('開始'+d.name,{type:'process',recipe:k},'full')}</article>`).join('')}</section><section class="panel"><h3>取得材料</h3><p>先派隊探索礫架材料倉、熱交換斷管、西側廢機場等地。材料從有限地區存量扣除，返營才入庫。滿包時留在原地。</p>${action('前往外拓','tab-explore','full')}${action('返回基地','tab-base','full')}<p class="muted">如需備份原存檔，使用下方匯出；本版同一存檔鍵升至schema6，舊版不能讀取新檔。</p>${action('匯出目前存檔 JSON','backup-save','full')}${archivedLegacy?action('匯出升級前原始存檔','backup-legacy','full'):''}</section>`;}
function explore(){const active=G.missions(s);const cards=active.map(m=>`<section class="panel" data-trip="${m.id}"><h2>外拓隊在途${m.rally?' · 聯合集結':''}</h2><p>${esc(G.SITES[m.site].name)} · ${m.ids.length}名兵員</p><p>口糧 <b data-trip-value="food">${m.food}</b> · 已採合金 <b data-trip-value="alloy">${m.alloy}</b> · 額外口糧 <b data-trip-value="cargoFood">${m.cargoFood}</b></p><p>背包 <b data-trip-value="weight">${G.packUsed(m)}</b>/${G.packCap(m)} 重量（按出發編制） · 殘材 <b data-trip-value="scrap">${m.cargo.scrap}</b> · 零件 <b data-trip-value="parts">${m.cargo.parts}</b> · 工具包 <b data-trip-value="tool">${m.cargo.tool}</b></p><p>野外威脅：攻${m.raid.attack} · ${m.deep&&['hold','search','outbound'].includes(m.deep.phase)?'需下達撤離指令 · 基礎剩餘行程':'預計返營'} <b data-trip-value="time">${fmt(m.end-s.time)}</b></p>${m.rally?`<p>盟友：${esc(G.FACTIONS[m.rally.faction].name)} · <b data-trip-value="ally">${s.time>=m.rally.arrival?'已抵達':'在途'}</b> · ${m.rally.ids.length}人</p>`:''}<div class="meter"><i data-progress="trip" style="width:${100*(s.time-m.start)/(m.end-m.start)}%"></i></div><p class="muted">物資及接應人員返營才入帳；基地仍可獨立遇襲。</p>${deepPanel(m)}</section>`).join('');if(active.length>=(s.build.command===2?2:1))return cards;if(!G.freeSlot(s))return cards+`<section class="panel"><h3>背包尚未清空</h3><p>先處理返營卸貨區，再出發。</p>${action('查看卸貨區','tab-storage','full primary')}</section>`;const opts=[['gather','近側殘骸・採集（180秒）'],...(s.first?[['long','遠程殘骸・採集（900秒）']]:[]),...Object.entries(s.companions).filter(([_,c])=>c.phase==='ready').map(([k])=>[k,G.COMP[k].site+'・接應（300秒）']),...G.GROUPS.filter(g=>s.groups[g.id].phase==='ready').map(g=>[g.id,g.site+'・接應3人（300秒）']),...(s.first?G.mapSites(s).filter(d=>d.id!=='home'&&d.id!=='wreck'&&d.id!=='longwreck').map(d=>['site:'+d.id,d.name+'・探索（'+d.secs+'秒）']):[])];if(!opts.some(([k])=>k===target))target='gather';const route=Object.entries(G.COMP).find(([k,p])=>p.route===target&&s.companions[k].project);if(!route)short=false;const material=!!G.MATERIAL_SITES[G.siteFor(target)]&&s.first;if(!material||!G.stock(s,'tool'))useTool=false;return cards+`<section class="panel"><h2>岩谷外拓</h2><p class="muted">近程採集180秒、遠程900秒、接應300秒；每趟均有獨立威脅，派出後基地留守至少2人；出發前請比較隊伍戰力與威脅。</p><label class="field">目的地<select id="target">${opts.map(([k,v])=>`<option value="${k}" ${target===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="row" style="margin:10px 0"><label class="field">兵員<select id="crew">${[2,3,4].map(n=>`<option ${crew===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">攜帶口糧<select id="food">${[4,5,6,7,8,9,10].map(n=>`<option ${food===n?'selected':''}>${n}</option>`).join('')}</select></label></div>${material?`<label class="field">採集優先<select id="priority"><option value="alloy" ${priority==='alloy'?'selected':''}>先合金</option><option value="materials" ${priority==='materials'?'selected':''}>先殘材／零件</option></select></label>${G.stock(s,'tool')?`<label><input id="useTool" type="checkbox" ${useTool?'checked':''}> 攜帶1工具包，設備箱有零件時可額外拆取</label>`:''}`:''}${route?`<label><input id="short" type="checkbox" ${short?'checked':''}> 使用已完成工程路線（1合金，行程240秒）</label>`:''}<div class="panel"><p>待命 <b data-count="standby">${count('standby')}</b> · 出發後留營 <b data-stat="remain">${G.B(s)-G.T(s)-G.garrison(s)-crew}</b>名兵員</p><p>背包 ${crew*12+(vehicle&&target.startsWith('site:')?24:0)}重量 · 攜帶${food+(useTool?2:0)} · 預留搬運${crew*12+(vehicle&&target.startsWith('site:')?24:0)-food-(useTool?2:0)}</p><p>空床位 ${G.beds(s)-G.N(s)} · 滿包物資留在原地，返營才入庫。</p><p>基地剩餘口糧 <b data-stat="leftfood">${s.food-food}</b> · 出發後基地防禦 <b data-stat="departguard">${Math.max(0,G.guard(s)-G.role(s,'standby').slice(0,crew).reduce((n,p)=>n+1+G.bonus(p),0))}</b></p><p class="muted">本次野外威脅：攻${target.startsWith('site:')?G.SITES[G.siteFor(target)].threat:3}。本隊預計戰力 ${G.role(s,'standby').slice(0,crew).reduce((n,p)=>n+1+G.bonus(p),0)}。兵力不足會有永久傷亡。留守人員也需足夠；生產與施工兵不提供防禦。</p></div>${s.frontier.vehicle&&target.startsWith('site:')?`<label><input id="vehicle" type="checkbox" ${vehicle?'checked':''}> 使用探索車（1合金燃料，+24重量，耐久${s.frontier.vehicle.hp}%）</label>`:''}${cmd('確認出發',{type:'depart',target,crew,food,short,priority,tool:useTool,vehicle:!!(vehicle&&target.startsWith('site:'))},'full primary')}${specialTrips()}${s.build.command===2&&target.startsWith('site:')&&G.SITES[G.siteFor(target)].threat===4&&s.map[G.siteFor(target)].visited?Object.entries(s.radio.alliance.members).filter(([k,v])=>v.pact==='allied').map(([k])=>cmd('與'+G.FACTIONS[k].name+'集結 · 另1合金',{type:'rally',faction:k,site:G.siteFor(target),crew,food,priority,tool:useTool},'full')).join(''):''}</section>`;}
function worldMap(){
 const all=Object.values(G.SITES),known=G.mapSites(s),visited=all.filter(d=>s.map[d.id].visited),d=G.SITES[selectedSite],v=s.map[d.id],m=s.mission;
 const tiles=all.map(n=>{const q=s.map[n.id],sel=n.id===selectedSite,active=G.missions(s).some(m=>m.site===n.id);const t=q.visited?s.frontier.territory[n.id]:null;const terrain=n.id==='home'?'home':n.faction?'faction':n.renew?'water':n.threat>=4?'hazard':'rock';return `<button data-action="site-${n.id}" class="map-tile ${q.known?terrain:'fog'} ${sel?'chosen':''} ${t?.owner==='player'?'territory-own':t?.owner?'territory-ai':''}" aria-pressed="${sel}" aria-label="${q.known?esc(n.name):'未知區域'} ${n.x+1},${n.y+1}${active?'，隊伍在途':''}"><span class="tile-symbol">${!q.known?'?':active?'➤':n.id==='home'?'⌂':n.faction?'◉':n.renew?'≈':q.visited?'✓':'◇'}</span><span class="tile-name">${q.known?esc(n.name):'未探索'}${t?.owner?' · '+(t.owner==='player'?'我方':'AI'):''}</span></button>`;}).join('');
 let detail='';if(!v.known){detail='<p>此區仍在迷霧中。從鄰接地點完成實地任務，或接收電台座標，才可揭露。</p>';}else if(d.id==='home'){detail=`<p>岩谷營地 · 目前守備 ${G.guard(s)} · 兵員 ${G.B(s)}人</p>${action('回到基地','tab-base','primary full')}`;}else{const key=Object.keys(G.RESCUE_SITE).find(k=>G.RESCUE_SITE[k]===d.id),person=key&&(s.companions[key]||s.groups[key]);let dest=d.id==='wreck'?'gather':d.id==='longwreck'?'long':'site:'+d.id;detail=`<div class="row"><span class="chip">${v.visited?'已實地探索':'已取得座標'}</span><span class="chip">${d.level===2?'一般探索需指揮艙L2':'近區'}</span></div><p>野外威脅：攻${d.threat} · 整趟 ${d.secs}秒</p>${v.visited?`<p>剩餘合金 <b data-map-alloy="${d.id}">${v.alloy}</b>／${d.alloy} · 口糧 <b data-map-food="${d.id}">${v.food}</b>／${d.food}</p>${d.renew?'<p class="muted">可再生口糧：每300秒補2，最多回到原儲量。</p>':'<p class="muted">有限物資，採完不會自動補滿。</p>'}`:'<p class="muted">精確儲量須待隊伍實際返營後揭露。</p>'}${G.missions(s).length>=(s.build.command===2?2:1)?'<p class="accent">外拓隊列已滿。</p>':!s.first&&d.id!=='wreck'?'<p>先完成首次近側採集。</p>':action('設定探索隊伍','map-depart-'+dest,'primary full')+`<p class="muted">實際派遣條件及成本以外拓頁為準。</p>`}${person&&person.phase==='ready'&&G.missions(s).length<(s.build.command===2?2:1)?action('安排實體接應','rescue-'+key,'full'):person&&['lead','contact','waiting'].includes(person.phase)?action('查看此區電台訊息','tab-radio','full'):''}${v.visited&&s.logistics.sites[d.id]?`<p>殘材 <b data-material-site="${d.id}" data-material-key="scrap">${s.logistics.sites[d.id].scrap}</b> · 零件 <b data-material-site="${d.id}" data-material-key="parts">${s.logistics.sites[d.id].parts}</b>（有限）</p>`:''}${d.faction&&v.visited?action('查看勢力通訊','tab-radio','full'):''}${v.visited&&s.frontier.territory[d.id]?`<p>據點：${s.frontier.territory[d.id].owner==='player'?'我方控制':s.frontier.territory[d.id].owner?esc(G.FACTIONS[s.frontier.territory[d.id].owner].name):'中立'} · 防線${s.frontier.territory[d.id].fort}</p>${action('據點與殖民指揮','tab-frontier','full')}`:''}`;}
 return `<section class="panel world-panel"><div class="map-title"><div><div class="tag">PLANETARY SURVEY / 01</div><h2>岩谷星域・區域地圖</h2></div><span class="chip">${visited.length}/30 已探索</span></div><p class="muted">點選地點查看資料，派隊實地探索。未知地區不顯示真名及資源。基地仍可能遇襲。</p><div class="map-grid" aria-label="6欄5列區域地圖">${tiles}</div><div class="map-legend"><span>⌂ 營地</span><span>◇ 已知</span><span>✓ 已探索</span><span>≈ 再生</span><span>◉ 勢力</span><span>? 未知</span></div><p class="muted">已取得 ${known.length}/30 個座標。${G.missions(s).map(m=>'外拓隊：'+esc(G.SITES[m.site].name)).join('；')}</p></section><section class="panel" id="map-detail"><h3>${v.known?esc(d.name):'未知區域'} · ${d.x+1},${d.y+1}</h3>${detail}</section><section class="panel"><h3>勢力聯絡</h3>${Object.entries(G.FACTIONS).map(([k,f])=>`<p>${s.factions[k].status==='unknown'?'未建立聯絡':esc(f.name)} · ${s.factions[k].status==='unknown'?'尚未探索':s.radio.alliance.members[k].pact==='allied'?'防禦盟友':s.radio.alliance.members[k].pact==='pending'?'談判中':s.factions[k].status==='contact'?'已聯絡':'互助交易'}</p>`).join('')}<p class="muted">指揮艙L2開放雙隊；已偵察高威脅區可邀盟友聯合討伐。殖民指揮24兵後可在殖民頁查看據點爭奪。</p></section>`;
}
function radioThread(k){const messages=s.radio.threads[k]?.messages||[];const bubble=m=>`<div class="radio-bubble ${m.side}" data-message-id="${esc(m.id)}"><small><span class="direction">${m.side==='player'?'TX / 已發送':m.side==='system'?'LOG / 系統':'RX / 接收'}</span> · 模擬 ${fmt(m.time)}${m.side==='remote'&&!seenRX.has(m.id)?' · 新訊':''}</small><p>${esc(m.text)}</p></div>`;return `<div class="radio-thread">${messages.length>4?`<details data-detail="thread-${k}" ${open.has('thread-'+k)?'open':''}><summary>早前通訊（${messages.length-4}則）</summary>${messages.slice(0,-4).map(bubble).join('')}</details>`:''}${messages.slice(-4).map(bubble).join('')}${unreadRX(k)?action('標記已讀 · '+unreadRX(k),'read-radio-'+k,'full read-receipt'):''}</div>`;}
function radio(){const buckets={reply:[],waiting:[],ready:[],history:[]};const card=(bucket,k,title,status,body)=>buckets[bucket].push(`<section class="panel radio" data-radio-channel="${k}" data-radio-bucket="${bucket}"><div class="frequency"><span class="led ${bucket==='waiting'?'amber':''}"></span> ${bucket==='waiting'?'STANDBY':bucket==='history'?'LOG':'RX'} / ${status==='待核實'||title.includes('未知')||k==='warning'?'來源待核實':'已記錄頻道'} ${unreadRX(k)?' · 未讀 '+unreadRX(k):''}</div><div class="radio-head"><h3>${esc(title)}</h3><span class="chip">${esc(status)}</span></div>${radioThread(k)}<div class="radio-actions">${body}</div></section>`);const phaseBucket=c=>['lead','contact'].includes(c.phase)?'reply':['waiting','transit','approaching'].includes(c.phase)?'waiting':c.phase==='returned'&&c.project?'history':'ready';
for(const [k,c]of Object.entries(s.companions)){if(c.phase==='unknown')continue;const p=G.COMP[k],known=c.phase!=='lead';const body=c.phase==='lead'?cmd(p.verify,{type:'inspect',id:k},'full'):c.phase==='contact'?cmd(p.paid,{type:'decide',id:k,option:'paid'},'full')+cmd(p.free,{type:'decide',id:k,option:'wait'},'full'):c.phase==='waiting'?`<p>遠端核路中 · <b data-wait="${k}">${fmt(c.due-s.time)}</b></p>`:c.phase==='ready'?action('安排實體接應','rescue-'+k,'primary full'):c.phase==='transit'?'<p class="accent">接應隊在途；未歸隊。</p>':`<p class="accent">✓ 已實際返營</p>${c.project?`<p>✓ ${esc(p.project)}完成；解鎖指定可選接應路線。</p>`:cmd('協作：'+p.project+' · 1合金',{type:'project',id:k},'full')}`;card(phaseBucket(c),k,(known?p.name:'未知短頻')+' · '+p.site,{lead:'待核實',contact:'待回覆',waiting:'等待回音',ready:'待接應',transit:'在途',returned:c.project?'已完成':'待工程'}[c.phase],body);}
for(const g of G.GROUPS){const c=s.groups[g.id];if(c.phase==='unknown')continue;const body=c.phase==='lead'?cmd('核對救生艙編號及身份',{type:'inspect',id:g.id},'full'):c.phase==='contact'?cmd('付2糧支援出口整理',{type:'decide',id:g.id,option:'paid'},'full')+cmd('遠端指導整理（30秒）',{type:'decide',id:g.id,option:'wait'},'full'):c.phase==='waiting'?`<p>等待出口整理 · <b data-wait="${g.id}">${fmt(c.due-s.time)}</b></p>`:c.phase==='ready'?`<p>需要3個空床位。現有 ${G.beds(s)-G.N(s)}。</p>${action('安排實體接應','rescue-'+g.id,'primary full')}${g.id==='pod1'&&G.B(s)<4?cmd('近側安全接近 · 2糧／120秒',{type:'approach',id:g.id},'full'):''}`:c.phase==='approaching'?`<p>生還者正沿安全路接近，遇襲暫緩 · <b data-wait="${g.id}">${fmt(c.due-s.time)}</b></p>`:c.phase==='transit'?'<p>接應隊在途。</p>':'<p class="accent">✓ 三人已實際接納，居民可自願入伍。</p>';card(c.phase==='returned'?'history':phaseBucket(c),g.id,g.site+' · '+(c.phase==='lead'?'未知來源':'身份已核實'),{lead:'待核實',contact:'待回覆',waiting:'等待回音',ready:'待接應',approaching:'在途',transit:'在途',returned:'已完成'}[c.phase],body);}
if(s.first)card(s.warningReply?'history':'reply','warning','不明巡查頻道',s.warningReply?'已回覆':'待回覆',s.warningReply?`<p>${s.warningReply==='negotiate'?'下輪巡查間隔延長，當前威脅仍存在。':'保持原警戒間隔。'}</p>`:cmd('嘗試談判',{type:'warning',option:'negotiate'},'full')+cmd('拒絕要求',{type:'warning',option:'refuse'},'full'));
for(const [k,d]of Object.entries(G.STORIES)){const v=s.radio.stories[k];if(v.phase==='hidden')continue;let body='';if(v.phase==='reply')body=d.options.map(([option,label])=>cmd(label,{type:'radio_reply',id:k,option},'full')).join('');else if(v.phase==='waiting')body=`<p>等待下一段回音 · <b data-radio-wait="${k}">${fmt(v.due-s.time)}</b></p>`;else if(v.phase==='ready')body=`<p>${esc(G.SITES[d.site].name)} · 真實調查後返營才結案。${s.build.command<G.SITES[d.site].level?' 需要指揮艙L2。':''}</p>${action('查看調查地點','radio-site-'+d.site,'primary full')}`;else body=`<p class="accent">${v.phase==='done'?'✓ 實地調查已結算':'頻道已封存'}</p>`;card({reply:'reply',waiting:'waiting',ready:'ready',done:'history',archived:'history'}[v.phase],k,d.title+' · 未知訊號',{reply:'待回覆',waiting:'等待回音',ready:'待調查',done:'已完成',archived:'已封存'}[v.phase],body);}
const fe=s.frontier.event;if(fe.phase!=='hidden')card(fe.phase==='reply'?'reply':fe.phase==='accepted'?'ready':'history','front-event','限時・中繼站異訊',({reply:'待回覆',accepted:'待探索',archived:'已封存',done:'已完成',expired:'已過期'})[fe.phase],fe.phase==='reply'?`<p>訊號有效期 · <b data-event-wait>${fmt(fe.due-s.time)}</b></p>`+cmd('追查記錄櫃',{type:'f_event',option:'accept'},'full')+cmd('封存訊號',{type:'f_event',option:'seal'},'full'):fe.phase==='accepted'?action('前往中繼站地圖','radio-site-relay','full')+'<p>選擇區域內部探索並搜索記錄櫃，返營結案。</p>':'');let h=`<div class="radio-console"><div class="eyebrow"><span class="led"></span> 遠燈號 / 備用短頻終端</div><h2>短頻電台</h2><div class="receiver"><svg viewBox="0 0 320 48" aria-hidden="true"><path d="M0 12H320M0 24H320M0 36H320" stroke="#315950" stroke-width=".6"/><path class="wave" d="${Array.from({length:81},(_,i)=>`${i?'L':'M'}${i*4} ${24+Math.sin(i*2.1)*Math.sin(i*.3)*14}`).join(' ')}" stroke="#79c7b8" fill="none" stroke-width="1.5"/></svg><span>${radioRX().length?'訊息紀錄可用':'監聽中・尚無來訊'}</span><small>波形為介面示意，非實測訊號品質</small></div><div class="radio-counts">${[['reply','待回覆'],['waiting','等待中'],['ready','待行動']].map(([k,label])=>`<span>${buckets[k].length}<small>${label}</small></span>`).join('')}</div><p class="accent">收件匣 · ${radioRX().filter(m=>!seenRX.has(m.id)).length} 則未讀</p><div class="radio-filters" aria-label="篩選頻道">${[['all','全部'],['reply','待回覆'],['waiting','等待'],['ready','待行動'],['history','封存／完成'],['diplomacy','外交']].map(([k,label])=>`<button data-action="radio-filter-${k}" aria-pressed="${radioFilter===k}">${label}</button>`).join('')}</div></div>`;if(!Object.values(buckets).some(a=>a.length))h+='<div class="panel"><p>目前只有雜訊。先完成近側殘骸採集，尋找可驗證的通訊資料。</p></div>';for(const [k,label]of [['reply','待回覆'],['waiting','等待與在途'],['ready','待行動'],['history','已完成／封存']])if(buckets[k].length&&(radioFilter==='all'||radioFilter===k))h+=`<h3 class="radio-section">${label} · ${buckets[k].length}</h3>${buckets[k].join('')}`;if(radioFilter!=='all'&&radioFilter!=='diplomacy'&&!buckets[radioFilter].length)h+='<div class="panel muted">此分類暫無頻道。</div>';if(!['all','diplomacy'].includes(radioFilter))return h;

h+=`<section class="panel"><h3>AI聯盟・外交頻道</h3><p>先實地拜訪勢力，再交易建立互信。盟友保有自己的兵員及有限庫存；基地遇襲才可請援。</p><p class="accent">現有 ${Object.values(s.radio.alliance.members).filter(v=>v.pact==='allied').length}/3 個防禦盟友</p>${Object.values(s.factions).every(v=>v.status==='unknown')?action('探索外界勢力','tab-map','full'):''}</section>`;
for(const [k,f] of Object.entries(G.FACTIONS)){const v=s.factions[k];if(v.status==='unknown')continue;const a=s.radio.alliance.members[k],t=s.radio.alliance.aid,own=t?.faction===k,live=G.allyLiving(a);h+=`<section class="panel radio" data-alliance="${k}"><div class="radio-head"><h3>${esc(f.name)}</h3><span class="chip">${{neutral:'中立',pending:'談判中',allied:'防禦盟友'}[a.pact]}</span></div><p>人口 ${a.civilians+live} · 守兵 ${live}（留守 ${live-Object.values(s.frontier.territory).filter(t=>t.owner===k).length-(own?t.ids.length:0)-G.missions(s).filter(m=>m.rally?.faction===k).reduce((n,m)=>n+m.rally.ids.length,0)}） · 口糧 ${a.food} · 合金 ${a.alloy}</p><p class="muted">本地未採資源：${a.foodReserve}糧、${a.alloyReserve}合金。每120秒有限採集，每300秒消耗最多2糧。</p><p>${esc(f.offer)}；剩餘交換 ${3-v.trades}/3 次。</p>${cmd('接受補給交換',{type:'trade',faction:k},'full')}<p class="muted">簽約條件：已完成 ${v.trades}/${G.ALLY[k].trades} 次交換、至少3名守兵及4糧。</p>${radioThread('ally-'+k)}${a.pact==='neutral'?cmd('提議共同防禦（60秒）',{type:'ally_request',faction:k},'full'):a.pact==='pending'?`<p>等待盟約回覆 · <b data-ally-wait="${k}">${fmt(a.due-s.time)}</b></p>${cmd('撤回提議',{type:'ally_cancel',faction:k},'full')}`:`<p class="accent">✓ 共同防禦協議有效</p>${own?`<p>支援隊 ${t.ids.length}人 · ${{enroute:'在途（未計戰力）',support:'已抵達（加入基地防禦）',returning:'返航中'}[t.phase]} ${t.due!==null?`<b data-aid-wait>${fmt(t.due-s.time)}</b>`:''}</p>${t.phase==='enroute'?cmd('撤回支援（不退物資）',{type:'ally_recall',faction:k},'full'):''}`:cmd('請求2名守兵 · 1合金／15秒',{type:'ally_aid',faction:k},'primary full')}${cmd('解除協議，保持中立',{type:'ally_leave',faction:k},'full')}`}</section>`;}h+=`<details class="panel" data-detail="hero" ${open.has('hero')?'open':''}><summary>船載人格檔案（非人口）</summary>${s.time<120?'尚未收到可識別資料。':s.time<240?'來源未明的呼號。':s.hero?`已保存${s.hero==='TRACE'?'璃棱的波形封存':'秋纓的安全建議'}。`:'<p>殘響的求救訊號</p>'+cmd('TRACE｜封存未知波形',{type:'hero',option:'TRACE'},'full')+cmd('SHELTER｜保護訊號來源',{type:'hero',option:'SHELTER'},'full')}</details>`;return h;}
function mailbox(){return `<h2>返營與戰報</h2>${s.ops?.report?`<section class="panel"><h3>最新聯合集結</h3><p>${esc(G.SITES[s.ops.report.site].name)} · ${esc(G.FACTIONS[s.ops.report.faction].name)} · ${esc(s.ops.report.result)} · 戰力 ${s.ops.report.defense}/${s.ops.report.attack} · 盟軍返營 ${s.ops.report.allies}人</p></section>`:''}<section class="panel"><h3>最新外拓</h3>${s.report?`<p>${s.report.site?esc(G.SITES[s.report.site].name)+' · ':''}返營 ${s.report.crew}人 · 帶回 ${s.report.food}糧、${s.report.alloy}合金 · 實際接納 ${s.report.joined}人</p>${s.report.materials?`<p>隨隊材料：${itemList(s.report.materials)}</p>`:''}${s.report.unload&&Object.keys(s.report.unload).length?`<p class="gold">當時留在卸貨區：${itemList(s.report.unload)}（目前存量請到倉庫確認）</p>${action('查看倉庫','tab-storage','full')}`:''}<small>結算 ${esc(s.report.id)} · ${fmt(s.report.time)}</small>`:'<p class="muted">尚未有外拓結算。</p>'}</section><section class="panel"><h3>最近侵略</h3>${s.lastRaid?`<p>${s.lastRaid.context} · ${s.lastRaid.result} · 防禦 ${s.lastRaid.defense}/${s.lastRaid.attack}</p><p>${s.lastRaid.dead?esc(s.lastRaid.dead)+' 永久陣亡':'無死亡'} · 損失 ${s.lastRaid.food}糧、${s.lastRaid.alloy}合金</p><small>${esc(s.lastRaid.id)}</small>`:'<p class="muted">尚未有侵略結算。</p>'}</section><section class="panel"><h3>真實事件記錄</h3>${s.history.slice().reverse().map(e=>`<div class="event"><small>${fmt(e.time)}</small> ${esc(e.text)}</div>`).join('')||'<p class="muted">尚無記錄。</p>'}</section>`;}
function roster(){return `<details class="panel" data-detail="roster" ${open.has('roster')?'open':''}><summary>編制明細 · 在營 <b data-stat="P">${G.P(s)}</b>人</summary><p>指揮官1 · 兵員 <b data-stat="B">${G.B(s)}</b> · 同伴 <b data-stat="R">${G.R(s)}</b> · 居民 <b data-stat="H">${G.H(s)}</b> · 外拓 <b data-stat="T">${G.T(s)}</b> · 據點留守 ${G.garrison(s)} · 歸隊總數 <b data-stat="N">${G.N(s)}</b></p><p>床位 ${G.beds(s)} · 待命 ${count('standby')} · 生產 ${count('recycle')+count('supply')} · 值守 ${count('duty')}</p><div class="roster">${s.crew.map(p=>`<div class="person ${p.alive?'':'dead'}">${esc(p.name)} · ${esc(p.call)}<br>${roleNames[p.role]}${p.alive?' · T'+p.tier+(p.tier>=2?' · 裝備 '+p.kit+'%':''):''}</div>`).join('')}${s.residents.map(p=>`<div class="person">${esc(p.name)}<br>居民 · 自願入伍</div>`).join('')}${Object.entries(s.companions).filter(([_,c])=>c.phase==='returned').map(([k])=>`<div class="person">${esc(G.COMP[k].name)}<br>專業同伴</div>`).join('')}</div></details>`;}
function risk(){let h='';if(s.baseRaid){const r=s.baseRaid;h+=`<section class="panel ${r.phase==='battle'?'battle':'warning'}"><h3>⚠ 基地${r.phase==='battle'?'交戰中':'警報'}</h3><p>敵方攻3 · ${r.phase==='battle'?'鎖定總防禦 '+r.defense+'（盟軍 '+(r.allyPower||0)+'）':'本方防禦 <b data-stat="guard">'+G.guard(s)+'</b> + 已抵達盟軍 '+G.allyPower(s)} · <b data-stat="raidtime">${fmt(r.due-s.time)}</b></p><small>${r.phase==='battle'?'交戰期間不能改編制。':'請調回生產兵員或加強留守；外拓隊不會瞬移。'}</small>${r.phase==='warning'&&Object.values(s.radio.alliance.members).some(v=>v.pact==='allied')?action('前往外交頻道請求支援','tab-radio','full'):''}</section>`;}if(G.missions(s).some(m=>!m.raid.done&&m.raid.phase==='battle'))h+='<div class="notice">外拓隊正在交戰；基地威脅獨立結算。</div>';return h;}
function job(){return s.job?`<div class="notice">${esc(s.job.type==='build'?G.BUILD[s.job.target].name:s.job.type==='recruit'?'新兵訓練':s.job.type==='repair'?'路障修理':s.job.type==='process'?G.RECIPES[s.job.target].name:({workshop:'工坊L2',academy:'整備L2',research:'基礎研究',fabricate:'T2裝備製造',promote:'T2升階',kitrepair:'裝備維修',f_expand:'殖民指揮擴容',f_energy:'能源站施工',f_research:'T3研究',f_vehicle:'探索車製造',f_t3:'T3裝備與訓練',f_vehicle_repair:'探索車維修'}[s.job.type]||'兵員訓練／遣返'))} · 剩餘 <b data-stat="jobtime">${fmt(s.job.end-s.time)}</b> · 佔用1名兵員${s.job.type==='process'&&s.baseRaid?.phase==='battle'?' · 交戰停工':''}</div>`:'';}

function deepPanel(m){const d=m.deep;if(!d)return '';let h=`<div class="notice"><b>區域探索 · ${({outbound:'去程',hold:'等待指令',search:'搜尋中',return:'撤離返營'})[d.phase]}</b>${m.vehicle?' · 探索車':''}</div>`;if(d.phase==='hold')h+=s.frontier.rooms[m.site].map((r,i)=>`<div class="event">${G.ROOM_NAMES[m.site][i]} · ${r.done?'已搜索':'剩餘物資 '+r.scrap+'殘材 '+r.parts+'零件'} ${cmd('搜尋30秒',{type:'f_search',trip:m.id,node:i})}</div>`).join('')+cmd('帶現有物資撤離',{type:'f_return',trip:m.id},'full primary');return h;}
function specialTrips(){if(!s.first)return '';const site=G.siteFor(target),c={type:'depart',target:'site:'+site,crew,food,priority,vehicle:!!(vehicle&&target.startsWith('site:'))};let h='';if(G.ROOM_SITES.includes(site)&&G.SITES[site]&&s.map[site].known&&['gather','site:'+site].includes(target))h+=cmd('進入區域內部探索',{...c,deep:true},'full');if(s.frontier.level>=1&&target.startsWith('site:')&&G.FRONT_SITES.includes(site)&&s.map[site].visited&&!s.frontier.rescued.includes(site))h+=cmd('接應三名新生還者',{...c,rescue:true},'full');if(s.frontier.level>=1&&G.TERR_SITES.includes(site)&&s.map[site].visited)h+=cmd('出征爭奪據點（留守1兵）',{...c,claim:true},'full');return h;}
function layoutPage(){const a=G.layout(s),movable=a.filter(p=>!['command','recycle'].includes(p.id));const buildable=['housing','supply','armory','tower','wall'].filter(k=>k==='housing'||!s.build[k]);if(!movable.some(p=>p.id===placeId)&&!buildable.some(k=>'new:'+k===placeId))placeId=movable[0]?.id||'new:housing';const labels={command:'指揮',recycle:'回收',housing:'住所',supply:'補給',armory:'整備',tower:'瞭望',wall:'圍牆',workshop:'工坊',academy:'訓練',research:'研究',energy:'能源',research3:'T3研',vehicle:'車庫'};const occupied=(x,y)=>a.find(p=>p.x===x&&p.y===y||p.kind==='housing'&&(p.rot?p.x===x&&p.y+1===y:p.x+1===x&&p.y===y));const size=G.layoutSize(s),grid=Array.from({length:size*size},(_,i)=>{const x=i%size,y=Math.floor(i/size),p=occupied(x,y),name=p?labels[p.kind]:x===3&&y===7?'入口':'·';return `<button class="tile10 ${placeX===x&&placeY===y?'picked':''} ${p?'occupied':''}" data-action="place-${x}-${y}" aria-label="${x+1},${y+1} ${name}">${name}</button>`}).join('');return `<section class="panel"><h2>基地空間佈局 · ${size}×${size}</h2><p>指揮與回收為固定錨點。住所佔兩格。南入口相鄰圍牆才提供防禦：目前 +${G.wallPower(s)}。先選設施及位置，再確認搬移。</p>${action('返回設施','tab-base')}<div class="basegrid10" style="grid-template-columns:repeat(${size},minmax(44px,1fr))">${grid}</div><label class="field">建造／搬移設施<select id="placeId">${buildable.map(k=>`<option value="new:${k}" ${placeId==='new:'+k?'selected':''}>新建 ${labels[k]}</option>`).join('')}${movable.map(p=>`<option value="${p.id}" ${p.id===placeId?'selected':''}>${labels[p.kind]} ${p.id.startsWith('housing')?p.id.slice(7):''}</option>`).join('')}</select></label><label class="field">方向<select id="placeRot"><option value="0" ${!placeRot?'selected':''}>橫向</option><option value="1" ${placeRot?'selected':''}>直向</option></select></label><p>目標 ${placeX+1},${placeY+1} · 搬移不重置耐久</p>${placeId.startsWith('new:')?cmd('確認建造 · '+G.BUILD[placeId.slice(4)].cost+'合金 / '+G.BUILD[placeId.slice(4)].secs+'秒',{type:'f_build_at',target:placeId.slice(4),x:placeX,y:placeY,rot:placeRot},'full primary'):placeId?cmd('確認搬移',{type:'f_move',id:placeId,x:placeX,y:placeY,rot:placeRot},'full primary'):'<p>先在設施頁建造一座可搬移設施。</p>'}</section>`;}
function frontierPage(){const f=s.frontier;return `<section class="panel"><h2>殖民發展 · 09</h2>${action('返回基地','tab-base')}<p>現有兵員 ${G.B(s)} / ${G.cap(s)}；床位 ${G.beds(s)}；已接應新地區 ${f.rescued.length}/${G.FRONT_SITES.length}。24兵容量後，已探索地點開放三人生還者接應；仍須在居民頁訓練。</p>${f.level<3?cmd('升級指揮容量至'+[24,48,96][f.level]+' · '+(12+6*f.level)+'合金／120秒',{type:'f_expand'},'full'):''}${f.energy?'<p>能源站已完成</p>':cmd('建能源站 · 10合金2零件',{type:'f_energy'},'full')}${f.research?'<p>T3研究已完成</p>':cmd('T3研究 · 8合金2零件',{type:'f_research'},'full')}${f.vehicle?`<p>探索車耐久 ${f.vehicle.hp}% · ${G.missions(s).some(m=>m.vehicle)?'在途':'在營'}</p>${cmd('修理探索車 · 2合金1零件',{type:'f_vehicle_repair'},'full')}`:cmd('製造探索車 · 12合金4零件／180秒',{type:'f_vehicle'},'full')}${G.role(s,'standby').filter(p=>p.tier===2).map(p=>cmd(p.name+' 升T3 · 6合金2零件／180秒',{type:'f_t3',target:p.id},'full')).join('')}</section><section class="panel"><h2>星域據點 · 10</h2><p>24兵容量後AI會消耗自己的糧與合金建據點，守軍不能同時支援。每300秒消耗補給；玩家攻下據點須實際留1兵，不能攻擊盟友。</p>${G.TERR_SITES.map(k=>{const t=f.territory[k];return `<div class="event"><b>${s.map[k].known?G.SITES[k].name:'未探索區域'}</b><p>${s.map[k].visited?(t.owner==='player'?'我方':t.owner?G.FACTIONS[t.owner].name:'中立')+' · 防線'+t.fort:'尚未偵察控制權'}</p>${t.owner==='player'?cmd('撤回留守兵（60秒）',{type:'f_withdraw',site:k},'full'):s.map[k].visited?action('前往出征配置','map-depart-site:'+k,'full'):''}</div>`}).join('')}</section>`;}

function sig(){return JSON.stringify([s.first,s.paused,s.build,s.wallHp,s.crew.map(p=>[p.id,p.role,p.tier,p.kit]),s.residents,s.companions,s.groups,s.job,s.mission&&[s.mission.id,s.mission.raid.phase,s.mission.raid.done],s.baseRaid&&[s.baseRaid.id,s.baseRaid.phase],s.report?.id,s.lastRaid?.id,s.hero,s.time>=240?2:s.time>=120?1:0,s.warningReply,tab,error,tab==='map'?Object.values(s.map).map(v=>[v.known,v.visited]):null,s.factions,s.radio,s.logistics.racks,s.logistics.unload,s.logistics.output,!!G.stock(s,'tool'),s.frontier,G.missions(s).map(m=>[m.deep?.phase,m.deep?.node,m.vehicle,m.rescue,m.claim]),s.ops&&[s.ops.workshop,s.ops.academy,s.ops.research,s.ops.kits,s.ops.report,G.missions(s).map(m=>[m.id,m.raid.phase,m.raid.done,m.rally&&[m.rally.ids,s.time>=m.rally.arrival]])]]);}
function render(force=false){if(held&&!force){pending=true;return;}root.classList.toggle('reduce-motion',!motionEnabled);if(screen!=='game'||!s){root.innerHTML=screen==='intro'?introPage():screen==='archive'?archivePage():titlePage();return;}const f=document.activeElement,focus=f?.getAttribute('data-cmd')||f?.getAttribute('data-action')||f?.id;const focusDetail=f?.tagName==='SUMMARY'?f.parentElement?.dataset.detail:null;for(const d of root.querySelectorAll('details[data-detail]')){const k=d.dataset.detail;if(d.open)open.add(k);else open.delete(k);}if(tab==='mail'){readReport=s.report?.id||null;readRaid=s.lastRaid?.id||null;}const unread=(s.report?.id&&s.report.id!==readReport)||(s.lastRaid?.id&&s.lastRaid.id!==readRaid);const radioNew=Object.values({...s.companions,...s.groups}).filter(c=>['lead','contact'].includes(c.phase)).length+Object.values(s.radio.stories).filter(c=>c.phase==='reply').length+(s.first&&!s.warningReply?1:0)+(s.frontier.event.phase==='reply'?1:0);root.innerHTML=`<div class="wrap"><header class="header"><div><div class="tag">STARFALL / FIELD COMMAND</div><h1>墜星前哨</h1></div><span class="chip">${s.first?(s.frontier.level?'殖民發展 · 容量'+G.cap(s):'第一期重建'):'失事求生'}</span><div class="header-tools">${action('設定','settings')}</div></header>${settingsOpen?settings():''}<div class="stats">${stat('food','口糧',s.food)}${stat('alloy','合金',s.alloy)}${stat('soldiers','待命／兵員',count('standby')+'/'+G.B(s))}${stat('joined','已歸隊',G.R(s)+'/5')}</div><div class="toolbar"><span class="muted">模擬時間 <b data-stat="time">${fmt(s.time)}</b> · 防禦 <b data-stat="guard">${G.guard(s)}</b></span><div class="row"><label class="muted">速度 <select id="speed"><option value="1" ${speed===1?'selected':''}>1×</option><option value="5" ${speed===5?'selected':''}>5×</option><option value="15" ${speed===15?'selected':''}>15×</option></select></label>${cmd(s.paused?'繼續':'暫停',{type:'pause'})}</div></div>${error?`<div class="notice" role="alert">${esc(error)}</div>`:''}${!storage?'<div class="notice">本機儲存不可用：關閉頁面會失去本次進度。</div>':''}${risk()}${job()}${roster()}<div id="stage">${tab==='base'?base():tab==='explore'?explore():tab==='radio'?radio():tab==='map'?worldMap():tab==='storage'?storagePage():tab==='layout'?layoutPage():tab==='frontier'?frontierPage():mailbox()}</div><nav class="nav" aria-label="遊戲分頁">${[['base','⌂','基地'],['explore','◇','外拓'],['map','▧','地圖'],['radio','◉','電台'+(radioRX().filter(m=>!seenRX.has(m.id)).length?' · '+radioRX().filter(m=>!seenRX.has(m.id)).length:'')],['mail','▤','信箱'+(unread?' ●':'')]].map(([k,g,l])=>`<button data-action="tab-${k}" aria-current="${tab===k||['storage','layout','frontier'].includes(tab)&&k==='base'?'page':'false'}" class="${tab===k||['storage','layout','frontier'].includes(tab)&&k==='base'?'active':''}"><span class="glyph" aria-hidden="true">${g}</span>${l}</button>`).join('')}</nav></div>`;signature=sig();pending=false;if(focusDetail){const d=[...root.querySelectorAll('details[data-detail]')].find(d=>d.dataset.detail===focusDetail);d?.querySelector('summary')?.focus({preventScroll:true});}else if(focus){const n=[...root.querySelectorAll('button,select')].find(n=>(n.getAttribute('data-cmd')||n.getAttribute('data-action')||n.id)===focus);if(n&&!n.disabled)n.focus({preventScroll:true});}}
function patch(){for(const e of root.querySelectorAll('[data-material-site]'))e.textContent=s.logistics.sites[e.dataset.materialSite][e.dataset.materialKey];const u=G.used(s),cap=G.capacity(s);for(const e of root.querySelectorAll('[data-stock-used]'))e.textContent=u;for(const e of root.querySelectorAll('[data-item]'))e.textContent=G.stock(s,e.dataset.item);for(const e of root.querySelectorAll('[data-stock-bar]'))e.style.width=Math.min(100,u/cap*100)+'%';for(const e of root.querySelectorAll('[data-stock-note]'))e.textContent=u>cap?'超額存放：保留既有物資，先消耗或擴倉。':u===cap?'倉庫已滿：生產及入庫暫停。':'尚有 '+(cap-u)+' 重量空間。';for(const card of root.querySelectorAll('[data-trip]')){const m=G.missions(s).find(m=>m.id===card.dataset.trip);if(!m)continue;for(const e of card.querySelectorAll('[data-trip-value]')){const k=e.dataset.tripValue;e.textContent=k==='weight'?G.packUsed(m):['scrap','parts','tool'].includes(k)?m.cargo[k]:k==='time'?fmt(m.end-s.time):k==='ally'?(s.time>=m.rally.arrival?'已抵達':'在途'):m[k];}const bar=card.querySelector('[data-progress]');if(bar)bar.style.width=100*(s.time-m.start)/(m.end-m.start)+'%';}const vals={food:s.food,alloy:s.alloy,soldiers:count('standby')+'/'+G.B(s),joined:G.R(s)+'/5',time:fmt(s.time),guard:G.guard(s),P:G.P(s),B:G.B(s),R:G.R(s),H:G.H(s),T:G.T(s),N:G.N(s),remain:G.B(s)-G.T(s)-G.garrison(s)-crew,departguard:Math.max(0,G.guard(s)-G.role(s,'standby').slice(0,crew).reduce((n,p)=>n+1+G.bonus(p),0)),leftfood:s.food-food,tripfood:s.mission?.food,cargofood:s.mission?.cargoFood,tripalloy:s.mission?.alloy,triptime:s.mission?fmt(s.mission.end-s.time):'',raidtime:s.baseRaid?fmt(s.baseRaid.due-s.time):'',jobtime:s.job?fmt(s.job.end-s.time):''};for(const el of root.querySelectorAll('[data-stat]'))el.textContent=vals[el.dataset.stat]??'';for(const el of root.querySelectorAll('[data-count]'))el.textContent=count(el.dataset.count);for(const el of root.querySelectorAll('[data-event-wait]'))el.textContent=fmt(s.frontier.event.due-s.time);for(const el of root.querySelectorAll('[data-radio-wait]')){const c=s.radio.stories[el.dataset.radioWait];if(c?.due)el.textContent=fmt(c.due-s.time);}for(const el of root.querySelectorAll('[data-ally-wait]')){const a=s.radio.alliance.members[el.dataset.allyWait];if(a.due!==null)el.textContent=fmt(a.due-s.time);}for(const el of root.querySelectorAll('[data-aid-wait]')){const a=s.radio.alliance.aid;if(a?.due!=null)el.textContent=fmt(a.due-s.time);}for(const el of root.querySelectorAll('[data-wait]')){const c=s.companions[el.dataset.wait]||s.groups[el.dataset.wait];if(c?.due)el.textContent=fmt(c.due-s.time);}for(const el of root.querySelectorAll('[data-cmd]')){const c=JSON.parse(el.dataset.cmd),why=blocked?'存檔已停止；請重新載入。':G.reason(s,c);el.disabled=!!why;el.title=why;const n=el.nextElementSibling;if(n?.hasAttribute('data-reason'))n.textContent=why;}for(const el of root.querySelectorAll('[data-assign-reason]'))el.textContent=G.reason(s,{type:'assign',role:el.dataset.assignReason,delta:1});for(const el of root.querySelectorAll('[data-map-alloy]'))el.textContent=s.map[el.dataset.mapAlloy].alloy;for(const el of root.querySelectorAll('[data-map-food]'))el.textContent=s.map[el.dataset.mapFood].food;}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;sound('click');held=false;clearTimeout(holdTimer);if(b.dataset.cmd){const c=JSON.parse(b.dataset.cmd);if(['cancel_process','discard_unload'].includes(c.type)&&!window.confirm(b.textContent+'？'))return;command(c);return;}const a=b.dataset.action;if(a==='backup-save'||a==='backup-legacy'){const data=a==='backup-legacy'?archivedLegacy:raw??JSON.stringify({state:s,wall:lastWall});if(data===null)return;const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=a==='backup-legacy'?'starfall-before-upgrade.json':'starfall-save-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}if(a==='settings'){settingsOpen=!settingsOpen;render(true);return;}if(a==='feedback'){feedbackDialog();return;}if(a==='settings-title'){if(!window.confirm('返回主畫面？遊戲將停止目前頁面的計時。'))return;loadedAt=loadedWall=Date.now();screen='title';settingsOpen=false;restartPending=false;render(true);window.scrollTo(0,0);return;}if(a==='audio-toggle'){audioEnabled=!audioEnabled;savePrefs();if(audioEnabled)sound('click');render(true);return;}if(a==='motion-toggle'){motionEnabled=!motionEnabled;savePrefs();render(true);return;}if(['pref-radio','pref-alarm','pref-click'].includes(a)){if(a==='pref-radio')radioSound=!radioSound;if(a==='pref-alarm')alarmSound=!alarmSound;if(a==='pref-click')clickSound=!clickSound;savePrefs();render(true);return;}if(a==='title'){screen='title';restartPending=false;render(true);window.scrollTo(0,0);return;}if(a==='archive'){screen='archive';render(true);return;}if(a==='replay-intro'){restartPending=false;readOnlyReplay=true;screen='intro';prologue=0;render(true);return;}if(a==='new-journey'){if(blocked)return;if(s&&!window.confirm('重新開局會取代目前進度，並在本機保留一份舊檔。確定？'))return;restartPending=!!s;readOnlyReplay=false;screen='intro';prologue=0;render(true);window.scrollTo(0,0);return;}if(a==='intro-next'||a==='intro-prev'||a==='intro-skip'){prologue=a==='intro-skip'?3:Math.max(0,Math.min(3,prologue+(a==='intro-next'?1:-1)));render(true);window.scrollTo(0,0);return;}if(a==='continue'||a==='start'){if(blocked)return;if(s&&!restartPending){if(continueGame()){render(true);window.scrollTo(0,0);}else render(true);return;}if(a==='continue'||readOnlyReplay)return;if(s&&restartPending&&storage){try{if(localStorage.getItem(G.KEY)!==raw){blocked=true;storageConflict=true;throw Error('另一分頁已修改存檔，請重新載入。');}const key=G.KEY+'.backup.before-restart.'+s.revision;if(localStorage.getItem(key)===null)localStorage.setItem(key,raw);else if(localStorage.getItem(key)!==raw){error='已有重新開局備份；請先匯出目前存檔。為避免覆寫，未開新局。';screen='title';render(true);return;}}catch(e){error='無法備份舊檔，未開新局。'+e.message;screen='title';render(true);return;}}if(!commit(G.start())){if(raw===null&&storage&&!error.includes('另一分頁')){storage=false;error='本機儲存不可用，本次只在頁面內遊玩。';if(!commit(G.start())){render(true);return;}}else{screen='title';render(true);return;}}restartPending=false;loadedWall=null;seenRX.clear();knownRX.clear();lastWarning=null;open.clear();radioFilter='all';screen='game';tab='base';lastWall=Date.now();render(true);window.scrollTo(0,0);return;}if(a?.startsWith('read-radio-')){markRadio(a.slice(11));render(true);return;}if(a?.startsWith('radio-filter-')){radioFilter=a.slice(13);render(true);return;}if(a?.startsWith('tab-')){tab=a.slice(4);render(true);window.scrollTo(0,0);}else if(a?.startsWith('radio-site-')){selectedSite=a.slice(11);tab='map';render(true);window.scrollTo(0,0);}else if(a?.startsWith('place-')){const [x,y]=a.slice(6).split('-').map(Number);placeX=x;placeY=y;render(true);}else if(a?.startsWith('site-')){selectedSite=a.slice(5);render(true);}else if(a?.startsWith('map-depart-')){target=a.slice(11);short=false;tab='explore';render(true);window.scrollTo(0,0);}else if(a?.startsWith('rescue-')){target=a.slice(7);tab='explore';render(true);window.scrollTo(0,0);}});
root.addEventListener('change',e=>{const x=e.target;if(x.id==='speed'||x.id==='pref-speed'){if([1,5,15].includes(Number(x.value)))speed=Number(x.value);savePrefs();render(true);return;}if(x.id==='pref-volume'){if([0,25,50,60,75,100].includes(Number(x.value)))volume=Number(x.value);savePrefs();render(true);return;}if(x.id==='pref-text'){if([100,115,130].includes(Number(x.value)))textSize=Number(x.value);savePrefs();applyPrefs();render(true);return;}if(x.id==='crew')crew=Number(x.value);else if(x.id==='food')food=Number(x.value);else if(x.id==='target'){target=x.value;short=false;}else if(x.id==='short')short=x.checked;else if(x.id==='priority')priority=x.value;else if(x.id==='useTool')useTool=x.checked;else if(x.id==='vehicle')vehicle=x.checked;else if(x.id==='placeId')placeId=x.value;else if(x.id==='placeRot')placeRot=Number(x.value);else return;render(true);});
root.addEventListener('pointerdown',e=>{if(e.target.closest('button,select,summary')){held=true;clearTimeout(holdTimer);}});window.addEventListener('pointerup',()=>{if(held)holdTimer=setTimeout(()=>{held=false;if(pending)render();},500);});window.addEventListener('pointercancel',()=>{held=false;if(pending)render();});
function tick(){if(screen!=='game'||!s||s.paused||document.hidden||blocked)return;const d=Math.max(0,Math.floor((Date.now()-lastWall)/1000));if(!d)return;const elapsed=Math.min(900,d*speed);try{const n=G.advance(s,elapsed);if(!commit(n)){blocked=true;render(true);return;}if(sig()!==signature){if(held){pending=true;patch();}else render();}else patch();}catch(e){error=e.message;blocked=true;render(true);}}
document.addEventListener('visibilitychange',()=>{if(screen==='game'&&!document.hidden&&s&&!s.paused&&!blocked){const d=Math.min(900,Math.max(0,Math.floor((Date.now()-lastWall)/1000)));if(d){if(!commit(G.advance(s,d,{offline:true})))blocked=true;render(true);}}});loadPrefs();applyPrefs();load();render(true);root.setAttribute('data-ready','true');root.removeAttribute('style');setInterval(tick,1000);})();
